import{c as r,Q as t,j as a,m as d}from"./chunks/framework.DGHXLY8X.js";const u=JSON.parse('{"title":"Supported hardware","description":"","frontmatter":{},"headers":[],"relativePath":"reference/supported-hardware.md","filePath":"reference/supported-hardware.md","lastUpdated":1780591920000}'),o={name:"reference/supported-hardware.md"};function i(n,e,c,l,s,p){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="supported-hardware" tabindex="-1">Supported hardware <a class="header-anchor" href="#supported-hardware" aria-label="Permalink to &quot;Supported hardware&quot;">​</a></h1><p>VideoNode runs on any Linux host with a GPU and a V4L2 capture device. Hardware acceleration is currently tuned to Rockchip rk35xx; everywhere else it uses portable software backends. This page lists what each pipeline stage needs and what is validated today.</p><h2 id="support-matrix" tabindex="-1">Support matrix <a class="header-anchor" href="#support-matrix" aria-label="Permalink to &quot;Support matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Hardware-accelerated (Rockchip rk35xx today)</th><th>Portable software (any Linux GPU host)</th></tr></thead><tbody><tr><td>MJPEG decode</td><td>MPP (<code>librockchip-mpp</code>)</td><td>TurboJPEG</td></tr><tr><td>Color conversion (CSC)</td><td>RGA (<code>librga</code>)</td><td>libplacebo (Vulkan/GL)</td></tr><tr><td>H.264 / H.265 encode</td><td><code>h264_rkmpp</code> / <code>hevc_rkmpp</code></td><td><code>libx264</code> / <code>libx265</code>, or <code>*_vaapi</code></td></tr><tr><td>GPU compositing</td><td>Mali via the <code>panthor</code> DRM render node</td><td>any DRM render node libplacebo can open</td></tr></tbody></table><p>The accelerated column is what the packaged build targets today. The software column runs anywhere VideoNode is built from source against a working GPU.</p><h2 id="validated-platform" tabindex="-1">Validated platform <a class="header-anchor" href="#validated-platform" aria-label="Permalink to &quot;Validated platform&quot;">​</a></h2><ul><li><strong>Board:</strong> <a href="https://www.friendlyelec.com/index.php?route=product/product&amp;product_id=292" target="_blank" rel="noreferrer">FriendlyElec NanoPC-T6</a> (RK3588, 8GB / 64GB eMMC or higher). Other RK3588 boards work, but the encoder paths are tuned and validated against the T6.</li><li><strong>OS:</strong> Debian 13 (trixie) or newer. The packaged native binaries link trixie-era shared libraries, so <code>apt</code> refuses to install on bookworm or older.</li><li><strong>Architecture:</strong> the APT package is <code>arm64</code> only. Other architectures require <a href="./../development/building">building from source</a>.</li></ul><h2 id="minimum-requirements" tabindex="-1">Minimum requirements <a class="header-anchor" href="#minimum-requirements" aria-label="Permalink to &quot;Minimum requirements&quot;">​</a></h2><ul><li>Linux with a DRM render node (<code>/dev/dri/renderD*</code>). The composer needs a GPU that libplacebo or RGA can drive.</li><li>A V4L2 capture device (<code>/dev/video*</code>): USB UVC cameras, MIPI-CSI cameras, or HDMI capture cards. Verify with <code>v4l2-ctl --list-devices</code>.</li><li>An <code>ffmpeg</code> on <code>PATH</code> with a working H.264 or H.265 encoder. Run <code>videonode validate-encoders</code> to confirm; see <a href="./../operating/encoders">Encoders</a> for the precedence rules.</li></ul><p>To install on the validated platform, see <a href="./../getting-started/installation">Installing VideoNode</a>.</p>',10)])])}const m=r(o,[["render",i]]);export{u as __pageData,m as default};
